node -e '
const cands = {
  current: (x) => Math.round(x * 100) / 100,
  epsAdd: (x) => Math.round((x + Number.EPSILON) * 100) / 100,
  epsMul: (x) => Math.round((x * 100) * (1 + Number.EPSILON)) / 100,
};
const cases = [1.005, 1.234, 2.675, 1.015, 1.025, 0.145, -1.005, -1.234, 1, 1.999, 10.005];
for (const [name, fn] of Object.entries(cands)) {
  console.log(name, cases.map(c => `${c}:${fn(c)}`).join(" "));
}'
